\label{thm1}
Let $1<p<\infty$. Then
\begin{equation}\label{mthm1}
 \big\|(A_Nf)_{N\in\mathbb N}\big\|_
 {L_p(\mathcal N;\ell_\infty)}
 \lesssim_{p,P} \|f\|_{L_p(\mathcal N)}
\end{equation}
for every $f\in L_p(\mathcal N)$. Moreover, $A_Nf$ converges
bilaterally almost uniformly to an element of $L_p(\mathcal N)$
as $N\to\infty$.

\label{Key1-es}
Let $1<p<\infty$ and $N_0\geq3$. Then
\begin{equation*}
 \big\|(f*K_N)_{N_0<N<N_0^2}\big\|_
 {L_p(\mathcal A_{\mathbb Z}(\mathcal N);\ell_\infty)}
 \lesssim_{p,P} \log\log N_0\,
 \|f\|_{L_p(\mathcal A_{\mathbb Z}(\mathcal N))}
\end{equation*}
for every finitely supported $\mathcal S(\mathcal N)$-valued
function $f$ on $\mathbb Z$.

\label{pro:stein extrapolation}
Let $1<p\leq2$. Suppose that there exists $B>0$ such that, for every
finite von Neumann algebra $(\mathcal M,\tau)$,
\begin{equation}\label{L18 bound}
 \big\|(A_r(f))_{r\in\mathcal I}\big\|_
 {L_1(\mathcal A;\ell_\infty)}
 \leq B\|f\|_{L_p(\mathcal A)},
 \qquad f\in L_p(\mathcal A).
\end{equation}
Then, for every finite von Neumann algebra $(\mathcal M,\tau)$,
\begin{equation}\label{Lambdap8 bound}
 \big\|(A_r(f))_{r\in\mathcal I}\big\|_
 {\Lambda_p(\mathcal A;\ell_\infty)}
 \leq CB\|f\|_{L_p(\mathcal A)},
 \qquad f\in L_p(\mathcal A),
\end{equation}
where $C$ is an absolute constant.

\label{prop:inj term}
Let $q>2$ be an integer.                                                   
 Then
\begin{equation*}
 \left\|(D_i)_{i\in I}\right\|_
 {L_{\frac{q}{q-1}}(\mathcal N;\ell_\infty)}
 \lesssim_q
 \left\|\sum_{i\in I}a_i\right\|_q^{q-1}.
\end{equation*}

\label{Bo89-es1}
There exist constants $\delta_d,\varepsilon_0>0$, depending only
on $d=\deg P$, and $c_0=c_0(P)>0$ such that the following
assertions hold.
\begin{enumerate}
 \item[\rm(i)] If $\xi\in\mathfrak R_s$, then
 \begin{equation}\label{eq:Sdec-v2}
  |S(\xi)|\lesssim_{P} 2^{-s\delta_d}.
 \end{equation}

 \item[\rm(ii)] For every $\beta\in\mathbb T$,
 \begin{equation}\label{eq:wdec-v2}
  |1-w_N(\beta)|\lesssim_{P} |\beta|N^d,
  \qquad
  |w_N(\beta)|
  \lesssim_{P} (1+|\beta|N^d)^{-1/d}.
 \end{equation}

 \item[\rm(iii)] If $\xi=a/q$ is reduced,
 $q<N^{\varepsilon_0}$, and
 $|\alpha-\xi|<N^{-d+\varepsilon_0}$, then
 \begin{equation*}
  \left|
   \widehat K_N(\alpha)
   -S(\xi)w_N(\alpha-\xi)
  \right|
  \lesssim_{P} N^{-1/2}.
 \end{equation*}

 \item[\rm(iv)] For every $\alpha\in\mathbb T$,
 \begin{equation*}
  \left|
   \widehat K_N(\alpha)
   -\sum_{s=0}^\infty\widehat L_{s,N}(\alpha)
  \right|
  \lesssim_{P} N^{-c_0}.
 \end{equation*}
\end{enumerate}

\label{lem:M-p-v2}
For every $1<p<\infty$ and $s\geq1$,
\begin{equation*}
 \left\|
 \bigl(f*M_{s,k}\bigr)_{k\geq4^s}
 \right\|_{L_p(\mathcal A_{\mathbb Z}(\mathcal M);\ell_\infty)}
 \lesssim_{p,P}\|f\|_p.
\end{equation*}

\label{lem:continuous-v2}
For $p>1$, we have the following inequality,
\begin{equation*}
  \big\|\big(T_{w_N}(f)\big)_{N\in\mathbb N}\big\|_
  {L_p(\mathcal A_{\mathbb R}(\mathcal M);\ell_\infty)}
  \lesssim_{p,P}\|f\|_{L_p(\mathcal A_{\mathbb R}(\mathcal M))},
\end{equation*}
where $w_N$ is defined in the equation \eqref{w_N} and ${\mathcal{M}}$ is an arbitrary semifinite von Neumann algebra.

Without loss of generality, we may assume that $f\in \mathcal{S}(\mathbb{R})_+\otimes\mathcal{S}({\mathcal{M}})_+$. Then
  \begin{align*}
  T_{w_N}(f)(x)&=\int_{0}^1f(x-P(Ny))dy=\frac{1}{N}\int_{0}^Nf(x-P(y))dy.
  \end{align*}
 Recall that $P(t)=\sum_{i=1}^d b_i t^i$ with $b_d>0$.
Choose $C_P>0$ sufficiently large so that $P$ is strictly
increasing on $[C_P,\infty)$ and, for every $t\geq C_P$,
\[
 \frac12 b_dt^d\leq P(t)\leq 2b_dt^d.
\]
We also have, for every
$z\geq P(C_P)$,
\begin{equation*}
 \frac12 db_d^{1/d}z^{1-1/d}
 \leq P'\bigl(P^{-1}(z)\bigr)
 \leq 2db_d^{1/d}z^{1-1/d}.
\end{equation*}
  We set $N_P=[C_P]+1$, then we have
  \begin{align}\label{HLmax-es1}
\nonumber&\big\|\big(T_{w_N}(f)\big)_{N\in\mathbb N}\big\|_
{L_p(\mathcal A_{\mathbb R}(\mathcal M);\ell_\infty)}
\\&\lesssim \sum_{n=1}^{N_P}
\big\|T_{w_n}(f)\big\|_{L_p(\mathcal A_{\mathbb R}(\mathcal M))}
+\big\|\big(T_{w_N}(f)\big)_{N>N_P}\big\|_
{L_p(\mathcal A_{\mathbb R}(\mathcal M);\ell_\infty)}.
  \end{align}
On the one hand, for a fixed $n$, we have
\begin{equation}\label{HLmax-es2}
    \big\|T_{w_n}(f)\big\|_{L_p(\mathcal A_{\mathbb R}(\mathcal M))}
    \leq \|f\|_{L_p(\mathcal A_{\mathbb R}(\mathcal M))}.
\end{equation}
On the other hand, for $N>N_P$, we have
\begin{align*}
   T_{w_N}(f)(x)&=\frac{1}{N}\int_{0}^Nf(x-P(y))dy\\
   &\leq T_{w_{N_p}}(f)(x)+\frac{1}{N}\int_{N_P}^Nf(x-P(y))dy\\
   &=T_{w_{N_p}}(f)(x)+\frac{1}{N}\int_{P(N_P)}^{P(N)}\frac{f(x-y)}{P^{\prime}(P^{-1}(y))}dy\\
   &\lesssim_P (w_{N_P}\hat{f})^{\vee}(x)+\frac{1}{N^d}\int_{0}^{2b_dN^d}{f(x-y)}\Big({\frac{y}{N^d}\Big)}^{-1+\frac{1}{d}}dy.
  \end{align*}
  Therefore,  combining estimate \eqref{HLmax-es2} and \cite[Lemma 4.1]{CHW24}, we get
  \begin{equation}\label{HLmax-es3}
    \big\|\big(T_{w_N}(f)\big)_{N>N_P}\big\|_
    {L_p(\mathcal A_{\mathbb R}(\mathcal M);\ell_\infty)}
    \lesssim_{p,P} \|f\|_{L_p(\mathcal A_{\mathbb R}(\mathcal M))}.
  \end{equation}
We conclude by gathering estimates \eqref{HLmax-es1}, \eqref{HLmax-es2} and \eqref{HLmax-es3}.

\label{lem:cyclic-v2}
Let $\varphi$ be a fixed smooth function with support in $(-1/2,1/2)$, and let
$1\le q\leq D$.  Then
\begin{align}
\left\|
\left(\mathcal T_{
\sum_{a=0}^{q-1}w_N(.-a/q)
\varphi(D(.-a/q))} f
\right)_N
\right\|_{L_p(\mathcal A_{\mathbb Z}(\mathcal M);\ell_\infty)}
\lesssim_{p,P}\|f\|_p.                               \label{eq:cyclic-v2}
\end{align}

\label{lem:weighted-v2}
Assume $D\ge q$.  Then
\begin{align}
\left\|
\left(
\mathcal T_{\sum_{a=0}^{q-1}S(a/q)w_N(.-a/q)
\varphi(D(.-a/q))} f
\right)_N
\right\|_{L_p(\mathcal A_{\mathbb Z}(\mathcal M);\ell_\infty)}
\lesssim_{p,P}\|f\|_p.                               \label{eq:weighted-v2}
\end{align}

Define for $\xi\in \mathbb T$
\[
 b_{q,D}(\xi)
 =
 \sum_{a=0}^{q-1}
 S(a/q)\varphi(D(\xi-a/q)).
\]
Its inverse Fourier kernel is
\begin{equation*}
 \check b_{q,D}(n)
 =
 D^{-1}\check\varphi(n/D)
 \sum_{a=0}^{q-1}S(a/q) e^{2\pi ina/q}.
\end{equation*}
Using \eqref{eq:S-v2} and the orthogonality relation
\[
 \frac1q\sum_{a=0}^{q-1} e^{2\pi iam/q}
 =
 \begin{cases}
 1,&q\mid m,\\
 0,&q\nmid m,
 \end{cases}
\]
we obtain
\begin{align*}
\sum_{a=0}^{q-1}S(a/q) e^{2\pi ina/q}
&=
\frac1q\sum_{r=0}^{q-1}
\sum_{a=0}^{q-1}
 e^{2\pi ia(n-P(r))/q}
\notag\\
&=
\#\{0\le r<q:P(r)\equiv n\pmod q\}
=:r_q(n).
\end{align*}
The function $r_q$ is $q$-periodic and clearly
\begin{align*}
 \sum_{j=0}^{q-1}r_q(j)
 & =q.
\end{align*}
Therefore, writing $n=\ell q+j$ with $0\le j<q$, we get
\begin{align*}
\|\check b_{q,D}\|_{\ell_1}
&=
\sum_{\ell\in\mathbb Z}\sum_{j=0}^{q-1}
\frac1D
\left|
\check\varphi\left(\frac{\ell q+j}{D}\right)
\right|r_q(j)\\
&\le
\sum_{\ell\in\mathbb Z}\frac qD
\max_{0\le j<q}
\left|
\check\varphi\left(\frac{\ell q+j}{D}\right)
\right|.
\end{align*}
For any $0\leq x,y\leq \frac q D$, by the mean value theorem
$$ \left|\check\varphi\left(\frac{\ell q}{D} + x\right)-\check\varphi\left(\frac{\ell q}{D} + y\right)\right|\lesssim_\varphi \min\Big\{ 1,   \frac {D}{\ell^2q}\Big\}.$$
It follows that for any integer $K>0$
$$\sum_{\ell\in\mathbb Z}\frac qD
\max_{0\le j<q}
\left|
\check\varphi\left(\frac{\ell q+j}{D}\right)
\right|\lesssim_\varphi \int_{\mathbb R} |\check\varphi| + 2\frac{Kq}D +\frac D q \sum_{|\ell|\geq K} \frac 1{\ell^2}.$$
Optimizing over $K$ gives
$$\|\check b_{q,D}\|_{\ell_1}\lesssim_\varphi 1.$$
Let $B_{q,D}$ be the convolution operator with symbol $b_{q,D}$.
 Young's inequality implies
\begin{equation}\label{eq:B-bound-v2}
 \|B_{q,D}f\|_{L_p(\mathcal A_{\mathbb Z}(\mathcal M))}
 \lesssim_{\varphi}\|f\|_{L_p(\mathcal A_{\mathbb Z}(\mathcal M))}.
\end{equation}


Choose a smooth function $\widetilde\varphi$ which equals one on
$\operatorname{supp}\varphi$ and is supported in $(-1/2,1/2)$. Apply Lemma \ref{lem:cyclic-v2} to $B_{q,D}f$, with
$\widetilde\varphi$ in place of $\varphi$.  The symbol of the resulting Fourier multiplier in the variable $\xi$ is
\begin{align*}
&\left[
 \sum_{a=0}^{q-1}
 w_N(\xi-a/q)
 \widetilde\varphi(D(\xi-a/q))
 \right]b_{q,D}(\xi)\\
&\quad=
\sum_{a=0}^{q-1}\sum_{b=0}^{q-1}
S(b/q)w_N(\xi-a/q)
\widetilde\varphi(D(\xi-a/q))
\varphi(D(\xi-b/q)).
\end{align*}
Note that all terms with $a\ne b$ vanish.   Since $\widetilde\varphi=1$ on $\operatorname{supp}\varphi$, the resulting multiplier is exactly
\[
 \sum_{a=0}^{q-1}
 S(a/q)w_N(\xi-a/q)
 \varphi(D(\xi-a/q)).
\]
Lemma \ref{lem:cyclic-v2} and \eqref{eq:B-bound-v2} now give
\eqref{eq:weighted-v2}.

\label{lem:L2decay-v2}
There is $\delta>0$ such that, for every $s\ge1$,
\begin{equation}\label{eq:error-decay-v2}
 \left\|
 \bigl(f*(K_{2^k}-M_{s,k})\bigr)_{k\ge4^s}
 \right\|_{L_2(\mathcal A_{\mathbb Z}(\mathcal M);\ell_\infty)}
 \lesssim2^{-\delta s}\|f\|_2.
\end{equation}
Moreover, for every $s\ge2$,
\begin{equation}\label{eq:difference-decay-v2}
 \left\|
 \bigl(f*(M_{s,k}-M_{s-1,k})\bigr)_{k\ge4^s}
 \right\|_{L_2(\mathcal A_{\mathbb Z}(\mathcal M);\ell_\infty)}
\lesssim2^{-\delta s}\|f\|_2.
\end{equation}

\label{lem:layer-v2}
There is $\gamma>0$ such that, for every dyadic $u$,
\begin{equation}\label{eq:layer-v2}
 \left\|
 \bigl(\mathcal T_{\Psi_{u,N}}(f)\bigr)_N
 \right\|_{L_2(\mathcal A_{\mathbb Z}(\mathcal M);\ell_\infty)}
 \lesssim u^{-\gamma}\|f\|_2.
\end{equation}

\label{lem:comparison-v2}
There is {$\gamma'>0$} such that, for every $s\ge1$,
\begin{equation}\label{eq:comparison-v2}
 \left\|
 \bigl(
\mathcal T_{
 L_{2^k}^{(\le2^s)}-\widehat M_{s,k}}( f)
 \bigr)_{k\ge4^s}
 \right\|_{L_2(\mathcal A_{\mathbb Z}(\mathcal M);\ell_\infty)}
 \lesssim 2^{-\gamma's}\|f\|_2.
\end{equation}

\label{lem:packet-v2}
Let $Q\ge1$ and $E\subset Q^{-1}\mathbb Z\cap \mathbb T$.  Let $\chi$ be smooth and
\[
 \operatorname{supp}\chi\subset\left(-\frac1{2Q},\frac1{2Q}\right).
\]
For scalars $(c_\theta)_{\theta\in E}\in \ell_\infty$, consider the symbol on $\mathbb T$
$$H_N(\alpha)=\sum_{\theta\in E}c_\theta w_N(\alpha-\theta) \chi(\alpha-\theta).$$
Then, for every $f\in L_2(\mathcal A_{\mathbb Z}(\mathcal M))$,
\begin{equation*}
 \|(\mathcal T_{H_N}f)_N\|_{L_2(\mathcal A_{\mathbb Z}(\mathcal M);\ell_\infty)}
 \lesssim \sup_{\theta\in E}|c_\theta|\,\|f\|_2.
\end{equation*}
